# Test cases for portfolio_risk_assessment

# Mocking calculate_stock_volatility for testing, since it's not provided
def calculate_stock_volatility(prices):
    # Let's just use sample volatility: standard deviation of prices for simplicity
    import statistics
    if len(prices) <= 1:
        return 0.0
    return statistics.stdev(prices)

# Patching the function to use the mock within portfolio_risk_assessment
def portfolio_risk_assessment(portfolio):
    '''
    Takes a dict where keys are stock names and values have 'prices' list and 'allocation' float.
    For each stock, call calculate_stock_volatility(prices), multiply by allocation, sum all weighted volatilities.
    Returns: float representing total portfolio risk as weighted sum.
    '''
    total_risk = 0.0
    for stock in portfolio.values():
        volatility = calculate_stock_volatility(stock['prices'])
        weighted_volatility = volatility * stock['allocation']
        total_risk += weighted_volatility
    return total_risk

