# Sample/mock implementation for calculate_stock_volatility (since actual function isn't given)
def calculate_stock_volatility(prices):
    # volatility as standard deviation of price changes
    if len(prices) < 2:
        return 0.0
    changes = [prices[i+1] - prices[i] for i in range(len(prices)-1)]
    mean = sum(changes)/len(changes)
    var = sum((c - mean) ** 2 for c in changes) / len(changes)
    return var ** 0.5

